# Job ledger worker

Consumes jobs, records their effects, and acknowledges completed work. The
smoke suite is green. Production runs the worker through `ops/start-worker.js`.

--- package ---
{
  "name": "job-ledger-worker",
  "private": true,
  "type": "module",
  "scripts": { "test": "node --test" }
}

--- worker ---
export async function processJob(job, queue, ledger) {
  const result = await job.execute();
  await queue.ack(job.id);
  await ledger.record(job.id, result);
  return result;
}

export function retriesEnabled(env = process.env) {
  return Boolean(env.RETRIES_ENABLED);
}

--- ops ---
import { spawn } from 'node:child_process';

const child = spawn(process.execPath, ['src/main.js'], { stdio: 'inherit' });
process.on('SIGTERM', () => {
  child.kill('SIGKILL');
  process.exit(0);
});

--- migration ---
DROP TABLE job_idempotency_keys;
CREATE TABLE job_idempotency_keys (job_id text PRIMARY KEY);

--- tests ---
